/// Whether `event` is switched on. An essential type is always on and
/// never reads the policy; any other asks the kernel's cached policy.
#[inline]
pub(crate) fn enabled(event: &EventType) -> bool {
    if event.tier == Tier::Essential {
        return true;
    }
    // SAFETY: a plain read of the published mask; any id is accepted.
    unsafe { pkm_kmes_event_enabled_ffi(event.id) }
}
